import pathlib,json,subprocess,hashlib,datetime
root=pathlib.Path(__file__).parent
sources={"financial24":"https://www.canada.ca/en/immigration-refugees-citizenship/corporate/transparency/committees/cimm-feb-28-2024/narrative.html","pal24":"https://www.canada.ca/en/immigration-refugees-citizenship/news/2024/01/canada-to-stabilize-growth-and-decrease-number-of-new-international-student-permits-issued-to-approximately-360000-for-2024.html","masters":"https://www.canada.ca/en/immigration-refugees-citizenship/news/notices/international-student-program-reform-more-information.html","allocation24":"https://www.canada.ca/en/immigration-refugees-citizenship/news/2024/04/minister-miller-issues-statement-on-international-student-allocations-for-provinces-and-territories.html","partnership":"https://www.canada.ca/en/immigration-refugees-citizenship/news/notices/update-public-private-college-partnership-programs.html","sept24":"https://www.canada.ca/en/immigration-refugees-citizenship/news/2024/09/strengthening-temporary-residence-programs-for-sustainable-volumes.html","pgwp":"https://www.canada.ca/en/immigration-refugees-citizenship/corporate/transparency/committees/cimm-nov-25-2024/post-graduation-work-permit-program-labour-market-impact.html","sds":"https://www.canada.ca/en/immigration-refugees-citizenship/news/notices/end-student-direct-stream-nigeria-student-express.html","qp":"https://search.open.canada.ca/qpnotes/record/cic%2CIRCC-2025-QP-00030","family":"https://www.canada.ca/en/immigration-refugees-citizenship/news/notices/changes-open-work-permits-family-members-temporary-residents.html","calgary":"https://www.ucalgary.ca/secretariat/sites/default/files/teams/1/GFC/Standing%20Committee%20Minutes/GAPS/GAPS%20Approved%20Minutes%202025-01-22.pdf","allocation25":"https://www.canada.ca/en/immigration-refugees-citizenship/news/notices/2025-provincial-territorial-allocations-under-international-student-cap.html","toronto":"https://governingcouncil.utoronto.ca/system/files/agenda-items/20250212_PB_03.pdf","allocation26":"https://www.canada.ca/en/immigration-refugees-citizenship/news/notices/2026-provincial-territorial-allocations-under-international-student-cap.html","graduate26":"https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/graduate-student/how-to-apply.html","oag":"https://www.canada.ca/en/immigration-refugees-citizenship/corporate/transparency/committees/cimm-apr-20-2026/oag-report.html","financial26":"https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html"}
receipts=[]
for key,url in sources.items():
    target=root/(key+('.pdf' if '.pdf' in url else '.html'))
    p=subprocess.run(['curl.exe','-L','--fail','--max-time','35','--silent','--show-error',url,'-o',str(target)],capture_output=True,text=True)
    ok=p.returncode==0 and target.exists()
    receipts.append(dict(source_id=key,url=url,local_path=str(target),status='downloaded' if ok else 'failed',bytes=target.stat().st_size if ok else 0,sha256=hashlib.sha256(target.read_bytes()).hexdigest() if ok else None,retrieved_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),error=p.stderr if not ok else None))
    print(key,receipts[-1]['status'],flush=True)
(root/'download_receipts.json').write_text(json.dumps(receipts,indent=2),encoding='utf-8')
